// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address originalCEO = c.ceoAddress();
        vm.prank(caller);
        try c.DrugDealer() {
            // DrugDealer succeeded
            address newCEO = c.ceoAddress();
            assertTrue(caller == originalCEO ? (newCEO == caller) : (newCEO == originalCEO));
        } catch {
            // DrugDealer reverted
            assertTrue(caller != originalCEO);
        }
    }
}

